/**
 * The TS vault client against bytes the RUST program produced.
 *
 * `programs/mitra-vault/tests/golden/vault-layout.json` is generated by
 * `golden_layout.rs` from the program's own types, and every instruction in it was
 * accepted by the program's real `dispatch`. Nothing here compares the TS client
 * with itself: each assertion is TS output against Rust output, so a drift on
 * either side fails here rather than on devnet.
 */
import { readFileSync } from "node:fs";
import { PublicKey } from "@solana/web3.js";
import { describe, expect, it } from "vitest";
import {
  ACCOUNT, IX, VAULT_PROGRAM_ID,
  amendMandateIx, authorizationPda, authorizeIx, decodeAuthorization, decodeMandate, decodeVault,
  depositIx, initializeVaultIx, mandatePda, openMandateIx, spendAuthorizedIx, vaultPda,
  MANDATE_LEN_PRE_BINDING,
} from "@/lib/solana/vault-program";

const g = JSON.parse(readFileSync("programs/mitra-vault/tests/golden/vault-layout.json", "utf8"));
const key = (s: string) => new PublicKey(s);
const hex = (b: Buffer | Uint8Array) => Buffer.from(b).toString("hex");
const I = {
  principal: key(g.inputs.principal),
  holder: key(g.inputs.holder),
  engine: key(g.inputs.engine),
  recipient: key(g.inputs.recipient),
  action: Buffer.from(g.inputs.action, "hex"),
  limit: BigInt(g.inputs.limit),
  ceiling: BigInt(g.inputs.ceiling),
  expiresAt: BigInt(g.inputs.expiresAt),
  amount: BigInt(g.inputs.amount),
  deposit: BigInt(g.inputs.deposit),
};

describe("identifiers match the program", () => {
  it("program id", () => {
    expect(VAULT_PROGRAM_ID.toBase58()).toBe(g.programId);
  });

  it("every instruction and account discriminator", () => {
    expect(hex(IX.initializeVault)).toBe(g.discriminators.initialize_vault);
    expect(hex(IX.deposit)).toBe(g.discriminators.deposit);
    expect(hex(IX.openMandate)).toBe(g.discriminators.open_mandate);
    expect(hex(IX.authorize)).toBe(g.discriminators.authorize);
    expect(hex(IX.spendAuthorized)).toBe(g.discriminators.spend_authorized);
    expect(hex(IX.amendMandate)).toBe(g.discriminators.amend_mandate);
    expect(hex(ACCOUNT.vault)).toBe(g.discriminators["account:Vault"]);
    expect(hex(ACCOUNT.mandate)).toBe(g.discriminators["account:Mandate"]);
    expect(hex(ACCOUNT.authorization)).toBe(g.discriminators["account:Authorization"]);
  });

  it("every PDA and bump", () => {
    const [v, vb] = vaultPda(I.principal);
    const [m, mb] = mandatePda(I.principal, I.holder);
    const [a, ab] = authorizationPda(m, I.action);
    expect([v.toBase58(), vb]).toEqual([g.pdas.vault.address, g.pdas.vault.bump]);
    expect([m.toBase58(), mb]).toEqual([g.pdas.mandate.address, g.pdas.mandate.bump]);
    expect([a.toBase58(), ab]).toEqual([g.pdas.authorization.address, g.pdas.authorization.bump]);
  });
});

describe("instruction data is byte-identical to what dispatch accepted", () => {
  it("initialize_vault and deposit", () => {
    expect(hex(initializeVaultIx(I.principal).data)).toBe(g.instructions.initialize_vault);
    expect(hex(depositIx(I.principal, vaultPda(I.principal)[0], I.deposit).data)).toBe(g.instructions.deposit);
  });

  it("open_mandate", () => {
    const ix = openMandateIx({ principal: I.principal, holder: I.holder, limit: I.limit, ceiling: I.ceiling, expiresAt: I.expiresAt, policyEngine: I.engine });
    expect(hex(ix.data)).toBe(g.instructions.open_mandate);
  });

  it("authorize", () => {
    const ix = authorizeIx({ engine: I.engine, principal: I.principal, holder: I.holder, action: I.action, amount: I.amount, recipient: I.recipient });
    expect(hex(ix.data)).toBe(g.instructions.authorize);
  });

  it("spend_authorized", () => {
    const ix = spendAuthorizedIx({ principal: I.principal, holder: I.holder, action: I.action, recipient: I.recipient });
    expect(hex(ix.data)).toBe(g.instructions.spend_authorized);
  });

  it("amend_mandate (revoke)", () => {
    const ix = amendMandateIx({ signer: I.holder, principal: I.principal, holder: I.holder, limit: I.limit, ceiling: I.ceiling, expiresAt: I.expiresAt, revoke: true });
    expect(hex(ix.data)).toBe(g.instructions.revoke);
  });
});

describe("account order is what dispatch was handed (golden accountMetas)", () => {
  type Meta = [string, boolean, boolean];
  const keys = (ix: { keys: Array<{ pubkey: PublicKey; isSigner: boolean; isWritable: boolean }> }): Meta[] =>
    ix.keys.map((k) => [k.pubkey.toBase58(), k.isSigner, k.isWritable]);

  // open_mandate and authorize take the program account LAST on chain, for the
  // create_account CPI the in-process run skips — so the golden list is a prefix
  // and the one extra account must be exactly the program id.
  const expectWithCpiTail = (ix: Parameters<typeof keys>[0], golden: Meta[]) => {
    const k = keys(ix);
    expect(k.slice(0, golden.length)).toEqual(golden);
    expect(k.slice(golden.length)).toEqual([[VAULT_PROGRAM_ID.toBase58(), false, false]]);
  };

  it("open_mandate: principal signs, principal's vault named", () => {
    const ix = openMandateIx({ principal: I.principal, holder: I.holder, limit: 1n, ceiling: 1n, expiresAt: 1n, policyEngine: I.engine });
    expectWithCpiTail(ix, g.accountMetas.open_mandate);
    expect(ix.keys[0].pubkey.equals(I.principal) && ix.keys[0].isSigner).toBe(true);
  });

  it("authorize: the engine signs", () => {
    const ix = authorizeIx({ engine: I.engine, principal: I.principal, holder: I.holder, action: I.action, amount: 1n, recipient: I.recipient });
    expectWithCpiTail(ix, g.accountMetas.authorize);
    expect(ix.keys[0].pubkey.equals(I.engine) && ix.keys[0].isSigner).toBe(true);
  });

  it("spend_authorized: no signer, read-only mandate, exactly four accounts", () => {
    const ix = spendAuthorizedIx({ principal: I.principal, holder: I.holder, action: I.action, recipient: I.recipient });
    expect(keys(ix)).toEqual(g.accountMetas.spend_authorized);
    expect(ix.keys.some((k) => k.isSigner)).toBe(false);
  });
});

describe("decoders read the program's own account bytes", () => {
  it("vault", () => {
    const v = decodeVault(Buffer.from(g.accounts.vault, "hex"));
    expect(v.authority.equals(I.principal)).toBe(true);
    expect(v.bump).toBe(g.pdas.vault.bump);
    expect([v.available, v.total]).toEqual([I.deposit, I.deposit]);
  });

  it("mandate, bound to the principal and engine", () => {
    const m = decodeMandate(Buffer.from(g.accounts.mandate, "hex"));
    expect(m.holder.equals(I.holder)).toBe(true);
    expect([m.limit, m.ceiling, m.expiresAt, m.version, m.revoked]).toEqual([I.limit, I.ceiling, I.expiresAt, 1n, false]);
    expect(m.binding?.principal.equals(I.principal)).toBe(true);
    expect(m.binding?.policyEngine.equals(I.engine)).toBe(true);
  });

  it("a pre-binding mandate decodes as unbound, as the program reads it", () => {
    const legacy = Buffer.from(g.accounts.mandate, "hex").subarray(0, MANDATE_LEN_PRE_BINDING);
    expect(decodeMandate(legacy).binding).toBeNull();
  });

  it("a full-length mandate with the bound flag clear is unbound", () => {
    const b = Buffer.from(g.accounts.mandate, "hex");
    b[73] = 0;
    expect(decodeMandate(b).binding).toBeNull();
  });

  it("authorization before and after spend: same permit, consumed flips", () => {
    const issued = decodeAuthorization(Buffer.from(g.accounts.authorizationIssued, "hex"));
    const spent = decodeAuthorization(Buffer.from(g.accounts.authorizationConsumed, "hex"));
    expect(issued.recipient.equals(I.recipient)).toBe(true);
    expect([issued.amount, issued.consumed, hex(issued.action)]).toEqual([I.amount, false, g.inputs.action]);
    expect([spent.amount, spent.consumed]).toEqual([I.amount, true]);
  });

  it("a 98-byte (pre-F51) permit is refused", () => {
    expect(() => decodeAuthorization(Buffer.from(g.accounts.authorizationIssued, "hex").subarray(0, 98)))
      .toThrow("NOT_AN_AUTHORIZATION_ACCOUNT");
  });

  it("a vault is not a mandate and a mandate is not a permit", () => {
    expect(() => decodeMandate(Buffer.from(g.accounts.vault, "hex"))).toThrow();
    expect(() => decodeAuthorization(Buffer.from(g.accounts.mandate, "hex"))).toThrow();
  });
});
